def is_valid_parenthese(str1):
    stack, pchar = [], {"(": ")", "{": "}", "[": "]"}
    for parenthese in str1:
        if parenthese in pchar:
            stack.append(parenthese)
        elif not stack or pchar[stack.pop()] != parenthese:
            return False
    return len(stack) == 0

def rev(num):    
    rev_num = 0
    while (num > 0):  
        rev_num = (rev_num * 10 + num % 10) 
        num = num // 10  
    return rev_num
def check(n):    
    return (n == 2 * rev(n) - 1)

def next_Power_Of_2(n): 
    count = 0; 
    if (n and not(n & (n - 1))): 
        return n   
    while( n != 0): 
        n >>= 1
        count += 1
    return 1 << count;

