def newman_prime(n):
    count = 0
    m, p = 1, 1
    while True:
        new_m = m * 3 + p * 4
        new_p = m * 2 + p * 3
        m, p = new_m, new_p

        is_prime = True
        if p < 2:
            is_prime = False
        else:
            for i in range(2, int(p**0.5) + 1):
                if p % i == 0:
                    is_prime = False
                    break
        if is_prime:
            count += 1
            if count == n:
                return p

def get_total_number_of_sequences(m,n): 
	if n == 0: return 0
	dp = [1] * (m + 1)
	dp[0] = 0
	for _ in range(n - 1):
		new_dp = [0] * (m + 1)
		prefix_sum = [0] * (m + 1)
		for i in range(1, m + 1):
			prefix_sum[i] = prefix_sum[i-1] + dp[i]
		for i in range(1, m + 1):
			new_dp[i] = prefix_sum[i // 2]
		dp = new_dp
	return sum(dp)

